function form_token(): string { return '<input type="hidden" name="_token" value="'.e($_SESSION['csrf']).'">'; }
function rate_limited(string $email): bool { $s=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND ip=? AND attempted_at>DATE_SUB(NOW(), INTERVAL '.(int)config('LOGIN_DECAY_MINUTES','15').' MINUTE)'); $s->execute([$email,$_SERVER['REMOTE_ADDR']??'']); return (int)$s->fetchColumn() >= (int)config('LOGIN_MAX_ATTEMPTS','5'); }
function reset_link(string $email): void { $token=bin2hex(random_bytes(32)); db()->beginTransaction(); try { db()->prepare('DELETE FROM password_reset_tokens WHERE email=?')->execute([$email]); db()->prepare('INSERT INTO password_reset_tokens (email,token) VALUES (?,?)')->execute([$email,password_hash($token,PASSWORD_ARGON2ID)]); db()->commit(); send_reset_email($email,$token); log_event('password_reset_requested',['email'=>$email]); } catch(Throwable $e) { if(db()->inTransaction())db()->rollBack(); throw $e; } }
