if ($path==='/login' && $method==='POST') { csrf(); $email=strtolower(trim($_POST['email']??'')); if(rate_limited($email)) { log_event('login_rate_limited',['email'=>$email]); flash('error','Too many attempts. Try again later.'); redirect('/login'); } if(!attempt_login($email,$_POST['password']??'')) { db()->prepare('INSERT INTO login_attempts (email,ip) VALUES (?,?)')->execute([$email,$_SERVER['REMOTE_ADDR']??'']); log_event('login_failed',['email'=>$email]); flash('error','Invalid email or password.'); redirect('/login'); } db()->prepare('DELETE FROM login_attempts WHERE email=?')->execute([$email]); redirect('/'); }
