if ($path==='/reset-password' && $method==='POST') { csrf(); $email=strtolower(trim($_POST['email']??'')); $token=$_POST['token']??''; $s=db()->prepare('SELECT token,created_at FROM password_reset_tokens WHERE email=?'); $s->execute([$email]); $row=$s->fetch(); $error=valid_password($_POST['password']??'') ?: (($_POST['password']??'')!==($_POST['confirm_password']??'') ? 'Passwords do not match.' : null); if(!$row || strtotime($row['created_at']) < time()-(int)config('PASSWORD_RESET_MINUTES','60')*60 || !password_verify($token,$row['token'])) $error='This reset link is invalid or expired.'; if($error){flash('error',$error);redirect('/reset-password?email='.rawurlencode($email).'&token='.rawurlencode($token));} db()->beginTransaction(); try{db()->prepare('UPDATE users SET password=?,must_change_password=0 WHERE email=?')->execute([password_hash($_POST['password'],PASSWORD_ARGON2ID),$email]);db()->prepare('DELETE FROM password_reset_tokens WHERE email=?')->execute([$email]);db()->commit();log_event('password_reset',['email'=>$email]);}catch(Throwable $e){db()->rollBack();throw $e;} flash('success','Password changed. You can now sign in.');redirect('/login'); }
