if ($path==='/users' && $method==='GET') { require_super_admin(); $users=db()->query('SELECT id,name,email,role,status,created_at,last_login_at FROM users ORDER BY created_at DESC')->fetchAll(); $rows='';foreach($users as $u){$rows.='<tr><td>'.e($u['name']).'</td><td>'.e($u['email']).'</td><td>'.e($u['role']).'</td><td>'.e($u['status']).'</td><td>'.e($u['created_at']).'</td><td>'.e($u['last_login_at']?:'—').'</td><td><form method="post" action="/users/reset" style="margin:0">'.form_token().'<input type="hidden" name="email" value="'.e($u['email']).'"><button>Send Password Reset Link</button></form><form method="post" action="/users/password" style="margin:0"><input type="hidden" name="id" value="'.e((string)$u['id']).'">'.form_token().'<input name="password" type="password" placeholder="New password" required><input name="confirm_password" type="password" placeholder="Confirm password" required><button>Set password</button></form><form method="post" action="/users/role" style="margin:0"><input type="hidden" name="id" value="'.e((string)$u['id']).'">'.form_token().'<select name="role"><option value="admin"'.($u['role']==='admin'?' selected':'').'>Admin</option><option value="super_admin"'.($u['role']==='super_admin'?' selected':'').'>Super Admin</option></select><button>Update role</button></form></td></tr>'; } render('User Management','<table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th>Last login</th><th>Action</th></tr></thead><tbody>'.$rows.'</tbody></table>');exit; }
